INSERT INTO public.words (id, word, meaning, detailed_meaning, news_example, hint, related_words, visuals, sources) VALUES
(1181,'쿠즈네츠 가설','성장 초기엔 불평등이 커지다가 일정 소득 이후엔 줄어든다는 주장','쿠즈네츠 가설은 경제발전과 소득 불평등의 관계를 역U자 곡선으로 설명한다. 공업화 초기에는 소득이 일부에 몰리지만 성장이 이어지면 분배가 개선된다고 본다. 자본수익률이 성장률보다 높아 불평등이 커진다는 피케티의 주장과 대비된다.','','ㅋㅈㄴㅊㄱㅅ',ARRAY['지니계수','소득5분위배율','경제성장률','소득주도성장']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "나라가 처음 공업화될 땐 공장 주인 쪽으로 돈이 몰려요.\n더 발전하면 교육과 복지가 넓어져 격차가 다시 줄어든다는 생각이에요."}, {"type": "line", "title": "역U자 모양 (개념 예시)", "unit": "불평등 정도", "x": ["저소득", "중저소득", "중소득", "중고소득", "고소득"], "series": [{"name": "불평등", "values": [30, 45, 50, 42, 32]}], "caption": "성장 초기에 오르다가 일정 수준 이후 내려가요. 수치는 이해를 위한 예시예요."}]'::jsonb,ARRAY['tesat']::text[]),
(1182,'소득주도성장','임금과 가계소득을 늘려 소비를 키우고 총수요로 성장을 이끌려는 전략','소득주도성장은 분배를 개선해 가계 소득을 늘리면 소비가 늘고, 이것이 총수요를 키워 성장으로 이어진다는 주장이다. 소비성향이 높은 저소득층의 소득을 늘리는 데 초점을 둔다. 기업 비용 부담과 고용 감소 가능성을 두고 논쟁이 있다.','','ㅅㄷㅈㄷㅅㅈ',ARRAY['최저임금제','총수요','쿠즈네츠 가설','실질임금']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "월급이 오르면 사람들이 더 쓰고, 가게 매출이 늘어 다시 고용이 늘어나는 선순환을 노려요."}, {"type": "flow", "title": "소득주도성장의 논리", "steps": ["임금·가계소득↑", "소비↑", "총수요↑", "생산·고용↑"]}]'::jsonb,ARRAY['tesat']::text[]),
(1183,'구매관리자지수(PMI)','기업 구매 담당자 설문으로 경기 흐름을 보는 지수, 50이 기준','구매관리자지수(PMI)는 신규 주문, 생산, 고용, 재고 등을 구매 담당자에게 물어 만든 경기 지표다. 50보다 높으면 경기 확장, 낮으면 위축으로 해석한다. 기준이 100인 BSI·CSI와 헷갈리기 쉽다.','','ㄱㅁㄱㄹㅈㅈㅅ',ARRAY['기업경기실사지수(BSI)','소비자동향지수(CSI)','경기선행지수','경기']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "원자재를 사는 담당자는 주문이 늘고 주는 걸 가장 먼저 알아요.\n그들의 답을 모아 50보다 크면 경기가 좋아지는 쪽이에요."}, {"type": "table", "title": "설문형 경기지표 기준", "columns": ["지표", "누구에게", "기준"], "rows": [["BSI", "기업가", "100"], ["CSI", "소비자", "100"], ["PMI", "구매 담당자", "50"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1184,'실물경기변동이론','기술 진보 같은 실물 충격과 사람들의 최적 선택으로 경기변동을 설명하는 이론','실물경기변동이론(RBC)은 경기변동의 원인을 총수요가 아니라 기술 변화나 원자재 공급 같은 실물 충격에서 찾는다. 경기 변동은 경제주체가 바뀐 여건에 맞춰 최적으로 반응한 결과라고 본다. 그래서 정부의 경기안정화 정책이 필요 없거나 효과가 작다고 주장한다.','','ㅅㅁㄱㄱㅂㄷㅇㄹ',ARRAY['경기','총요소생산성(TFP)','경기조절정책(경제안정화정책)','가속도 원리']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "새 기술이 나오면 생산성이 좋아져 호황, 그 반대면 불황이 온다고 봐요.\n돈이나 수요보다 실제 생산 능력의 변화를 원인으로 봐요."}, {"type": "table", "title": "경기변동 이론 비교", "columns": ["이론", "원인"], "rows": [["케인스학파", "총수요 충격"], ["통화주의", "통화량 변화"], ["실물경기변동이론", "기술 같은 실물 충격"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1185,'가속도 원리','소득이나 소비가 늘면 그 변화분보다 투자가 크게 움직인다는 원리','가속도 원리는 생산을 늘리려면 설비가 필요하므로 소득 변화가 투자를 크게 자극한다는 이론이다. 승수효과와 함께 작용하면 소득과 투자가 서로를 키워 경기 확장과 수축이 커진다. 케인스학파가 경기변동이 지속되는 이유로 든다.','','ㄱㅅㄷㅇㄹ',ARRAY['승수효과','경기','실물경기변동이론','국내총투자율']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "빵 주문이 조금 늘어도 오븐을 새로 사야 하면 투자는 크게 늘어요.\n반대로 주문이 조금만 줄어도 오븐 구매는 뚝 끊겨요."}, {"type": "flow", "title": "승수와 가속도의 상호작용", "steps": ["정부지출↑", "소득↑ (승수효과)", "투자↑ (가속도 원리)", "소득 더 증가"]}]'::jsonb,ARRAY['tesat']::text[]),
(1186,'특화','잘하는 상품의 생산에 자원을 몰아 집중하는 것','특화는 각 나라나 사람이 상대적으로 잘하는 일에 집중해 생산하는 것이다. 특화한 뒤 서로 교환하면 무역 전보다 양쪽 모두 더 많이 소비할 수 있다. 절대우위론과 비교우위론 모두 특화와 교환의 이익을 설명한다.','','ㅌㅎ',ARRAY['절대우위','비교우위','국제분업','기회비용']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "요리 잘하는 사람은 요리만, 청소 잘하는 사람은 청소만 하면 둘 다 일이 빨리 끝나요.\n나라끼리도 같은 원리로 이득을 봐요."}, {"type": "table", "title": "특화하면 얼마나 늘까 (예시)", "columns": ["구분", "한국", "일본"], "rows": [["무역 전 소비", "X 5, Y 5", "X 5, Y 5"], ["특화 생산", "X 15", "Y 15"], ["7개씩 교환 뒤 소비", "X 8, Y 7", "X 7, Y 8"]], "caption": "두 나라 모두 무역 전보다 소비가 늘어요."}]'::jsonb,ARRAY['tesat']::text[]),
(1187,'국제분업','나라마다 유리한 상품을 나눠 생산하고 무역으로 교환하는 체계','국제분업은 각국이 비교우위가 있는 상품에 특화해 생산하고 서로 교환하는 구조다. 애덤 스미스의 절대우위론이 처음 근거를 제시했고 리카도의 비교우위론으로 발전했다. 오늘날에는 한 제품의 부품과 공정을 여러 나라가 나눠 맡는 글로벌 공급망으로 확장됐다.','','ㄱㅈㅂㅇ',ARRAY['특화','비교우위','절대우위','부가가치기준 무역(TiVA)']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "휴대폰 하나에도 여러 나라의 부품과 기술이 들어가요.\n나라마다 잘하는 일을 나눠 맡는 거예요."}, {"type": "flow", "title": "국제분업의 흐름", "steps": ["나라별 강점 파악", "강점 상품에 특화", "무역으로 교환", "모두 소비 증가"]}]'::jsonb,ARRAY['tesat']::text[]),
(1188,'신보호무역주의','선진국이 경쟁력을 잃은 산업을 비관세장벽 위주로 보호하는 흐름','신보호무역주의는 1970년대 이후 선진국이 사양산업과 고용을 지키려고 무역을 제한하는 경향을 말한다. 개발도상국이 새 산업을 키우려 관세를 쓰던 기존 보호무역주의와 달리 수입할당, 수출자율규제, 각종 규제 같은 비관세장벽을 주로 쓴다. 국제 협정의 관세 인하 약속을 피해 가는 수단이 되기도 한다.','','ㅅㅂㅎㅁㅇㅈㅇ',ARRAY['보호무역주의','비관세장벽','수출자율규제','유치산업']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "예전 보호무역은 가난한 나라가 어린 산업을 지키는 것이었어요.\n신보호무역은 잘사는 나라가 밀리는 산업을 지키려는 거예요."}, {"type": "table", "title": "보호무역주의 vs 신보호무역주의", "columns": ["구분", "누가", "무엇을", "수단"], "rows": [["보호무역주의", "주로 개발도상국", "새로 크는 공업", "관세 중심"], ["신보호무역주의", "주로 선진국", "사양산업", "비관세장벽 중심"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1189,'궁핍화 성장','수출품 생산이 늘었는데 교역조건이 나빠져 오히려 후생이 줄어드는 현상','궁핍화 성장은 한 나라가 수출 상품 생산을 크게 늘리면서 그 상품의 국제 가격이 떨어지는 경우에 나타난다. 같은 양의 수입품을 사려면 더 많이 수출해야 하므로 교역조건이 악화된다. 결국 GDP는 늘어도 국민의 실제 후생은 줄어들 수 있다.','','ㄱㅍㅎㅅㅈ',ARRAY['순상품교역조건지수','소득교역조건지수','근린궁핍화정책','대외의존도(무역의존도)']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "커피만 수출하는 나라가 커피를 두 배로 만들면 커피값이 폭락해요.\n더 많이 팔아도 사 올 수 있는 물건은 오히려 줄 수 있어요."}, {"type": "flow", "title": "궁핍화 성장 과정", "steps": ["수출품 생산 급증", "국제 가격 하락", "교역조건 악화", "GDP↑ 그러나 후생↓"]}]'::jsonb,ARRAY['tesat']::text[]),
(1190,'경제통합','여러 나라가 무역장벽을 낮추고 시장과 정책을 하나로 묶어 가는 과정','경제통합은 회원국 사이의 관세와 규제를 없애고 단계적으로 시장을 하나로 묶는 것이다. 자유무역지역, 관세동맹, 공동시장, 경제동맹, 완전경제통합 순으로 결합 정도가 깊어진다. 무역창출효과와 무역전환효과가 함께 나타난다.','','ㄱㅈㅌㅎ',ARRAY['자유무역협정(FTA)','관세동맹','공동시장','경제동맹']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "처음엔 관세만 없애다가 점점 사람, 돈, 정책까지 함께 쓰는 단계로 가요."}, {"type": "table", "title": "경제통합의 단계", "columns": ["단계", "내용"], "rows": [["자유무역지역(FTA)", "회원국끼리 관세 철폐"], ["관세동맹", "+ 비회원국에 공동 관세"], ["공동시장", "+ 노동·자본 이동 자유"], ["경제동맹", "+ 재정·통화 정책 협조"], ["완전경제통합", "하나의 경제처럼 운영"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1191,'관세동맹','회원국끼리 관세를 없애고 비회원국에는 같은 관세를 매기는 통합 단계','관세동맹은 자유무역지역에서 한 걸음 더 나아가 회원국이 대외 관세율을 공동으로 정하는 경제통합 단계다. FTA는 비회원국에 대한 관세를 각자 정하지만 관세동맹은 하나로 맞춘다. 그래서 비회원국 상품이 관세가 낮은 회원국을 거쳐 들어오는 우회 수입을 막을 수 있다.','','ㄱㅅㄷㅁ',ARRAY['경제통합','자유무역협정(FTA)','공동시장','관세']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "회원국끼리는 관세 0, 밖에서 오는 물건엔 모두 같은 관세를 매겨요.\n어느 나라로 들어오든 관세가 같아요."}, {"type": "table", "title": "FTA vs 관세동맹", "columns": ["구분", "회원국끼리", "비회원국에"], "rows": [["FTA", "관세 철폐", "각자 관세"], ["관세동맹", "관세 철폐", "공동 관세"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1192,'공동시장','관세동맹에 더해 회원국 사이 노동과 자본의 이동까지 자유롭게 한 통합 단계','공동시장은 상품뿐 아니라 사람과 자본 같은 생산요소도 회원국 사이를 자유롭게 오가도록 한 경제통합 단계다. 회원국끼리 관세를 없애고 대외 공동 관세를 두는 관세동맹의 내용을 포함한다. 다음 단계는 재정·통화 정책까지 협조하는 경제동맹이다.','','ㄱㄷㅅㅈ',ARRAY['관세동맹','경제동맹','경제통합','유럽연합(EU)']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "물건만이 아니라 사람도 다른 회원국에 가서 자유롭게 일하고, 돈도 자유롭게 투자할 수 있어요."}, {"type": "flow", "title": "통합이 깊어지는 순서", "steps": ["관세 철폐", "공동 관세", "노동·자본 이동 자유", "정책 협조"]}]'::jsonb,ARRAY['tesat']::text[]),
(1193,'경제동맹','공동시장에 더해 회원국이 재정·통화 정책까지 협조하는 통합 단계','경제동맹은 상품과 생산요소의 자유 이동에 더해 경제 정책을 조율하는 경제통합 단계다. 단일 통화를 쓰는 유로존이 대표적인 예로 꼽힌다. 이 단계를 넘어 하나의 경제처럼 운영하면 완전경제통합이 된다.','','ㄱㅈㄷㅁ',ARRAY['공동시장','경제통합','유럽연합(EU)','통화정책']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "회원국들이 같은 돈을 쓰고 경제 정책도 함께 맞추는 단계예요.\n유로를 쓰는 나라들이 대표적이에요."}, {"type": "table", "title": "공동시장 vs 경제동맹", "columns": ["구분", "포함 내용"], "rows": [["공동시장", "관세 철폐 + 공동 관세 + 노동·자본 이동"], ["경제동맹", "공동시장 + 재정·통화 정책 협조"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1194,'무역창출효과','경제통합으로 비싼 국내 생산이 더 싼 회원국 수입으로 바뀌는 효과','무역창출효과는 회원국 사이 관세가 없어지면서 효율이 낮은 국내 생산 대신 값싼 회원국 상품을 수입하게 되는 것이다. 자원이 더 효율적으로 쓰이므로 후생을 늘리는 좋은 효과로 평가된다. 반대 방향의 무역전환효과보다 클 때 경제통합이 이득이 된다.','','ㅁㅇㅊㅊㅎㄱ',ARRAY['무역전환효과','경제통합','자유무역협정(FTA)']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "국내에서 비싸게 만들던 물건을 관세가 사라진 회원국에서 더 싸게 사 와요.\n소비자는 이득이고 자원도 효율적으로 쓰여요."}, {"type": "table", "title": "무역창출 vs 무역전환", "columns": ["효과", "뜻", "평가"], "rows": [["무역창출효과", "비싼 국내 생산 → 싼 회원국 수입", "좋은 효과"], ["무역전환효과", "싼 비회원국 → 비싼 회원국 수입", "나쁜 효과"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1195,'무역전환효과','경제통합으로 더 싼 비회원국 대신 비싼 회원국에서 수입하게 되는 효과','무역전환효과는 관세 차별 때문에 원래 가장 싸게 만들던 비회원국 대신 관세가 없어진 회원국에서 수입하게 되는 것이다. 효율이 낮은 생산자에게 거래가 옮겨 가므로 후생을 줄이는 나쁜 효과로 평가된다. 경제통합의 이득은 무역창출효과와 이 효과의 크기를 비교해 판단한다.','','ㅁㅇㅈㅎㅎㄱ',ARRAY['무역창출효과','경제통합','관세동맹']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "원래 A국 물건이 제일 쌌는데, B국과만 관세를 없애서 B국 물건을 사게 됐어요.\n가장 싸게 만드는 곳에서 안 사니 손해예요."}, {"type": "flow", "title": "무역전환이 생기는 과정", "steps": ["회원국 관세만 철폐", "비회원국엔 관세 유지", "회원국 상품이 상대적으로 싸 보임", "효율 낮은 곳에서 수입"]}]'::jsonb,ARRAY['tesat']::text[]),
(1196,'요소가격 균등화 정리','자유무역이 나라 간 임금과 이자 같은 생산요소 가격 차이를 줄인다는 이론','요소가격 균등화 정리는 생산요소가 직접 이동하지 않아도 상품 무역만으로 요소 가격이 같아지는 쪽으로 움직인다는 이론이다. 노동이 풍부한 나라는 노동집약적 상품을 수출하며 임금이 오르고, 자본이 풍부한 나라는 이자가 오른다. 헥셔-올린 모형에서 도출되는 결론으로, 자유무역의 이점 가운데 하나로 꼽힌다.','','ㅇㅅㄱㄱㄱㄷㅎㅈㄹ',ARRAY['비교우위','국제분업','실질임금']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "일손이 많은 나라가 노동집약 상품을 수출하면 일손 수요가 늘어 임금이 올라요.\n그 결과 나라 간 임금 차이가 좁혀져요."}, {"type": "flow", "title": "요소가격이 가까워지는 과정", "steps": ["풍부한 요소로 만든 상품 수출", "그 요소 수요 증가", "요소 가격 상승", "나라 간 격차 축소"]}]'::jsonb,ARRAY['tesat']::text[]),
(1197,'관세','외국에서 들어오는 수입품에 정부가 매기는 세금','관세는 수입 상품 가격을 높여 국내 생산자를 보호하고 정부 수입을 얻는 무역 정책 수단이다. 소국이 관세를 매기면 국내 가격이 올라 생산자는 이득, 소비자는 손해를 보고 사중손실만큼 사회 후생이 줄어든다. 대국은 국제 가격을 끌어내려 교역조건이 개선되면 후생이 늘 수도 있다.','','ㄱㅅ',ARRAY['보호무역주의','사중손실','비관세장벽','상계관세']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "수입품에 세금을 붙이면 값이 올라 국산품이 덜 밀려요.\n대신 소비자는 더 비싸게 사야 해요."}, {"type": "table", "title": "소국이 관세를 매기면 (예시)", "columns": ["항목", "변화"], "rows": [["국내 가격", "2 → 4"], ["국내 생산", "20 → 40"], ["국내 소비", "80 → 60"], ["수입", "60 → 20"]], "caption": "생산자는 이득, 소비자는 손해, 사회 전체는 사중손실만큼 손해예요."}, {"type": "text", "title": "왜 중요할까?", "body": "관세가 오르면 수입 물가와 수출 기업 실적이 함께 흔들려서 무역 뉴스에서 자주 등장해요."}]'::jsonb,ARRAY['tesat']::text[]),
(1198,'비관세장벽','관세 대신 수입량 제한, 규제, 인증 같은 방법으로 수입을 막는 장치','비관세장벽은 수입할당, 수출자율규제, 까다로운 기술 기준이나 위생 검사처럼 세금이 아닌 방식으로 무역을 제한하는 수단이다. 관세 인하 협정을 피해 쓰기 쉬워 신보호무역주의의 주된 도구가 됐다. 수단에 따라 가격 상승으로 생기는 초과이윤이 돌아가는 곳이 다르다.','','ㅂㄱㅅㅈㅂ',ARRAY['관세','수입할당제','수출자율규제','신보호무역주의']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "세금을 매기지 않아도 수입을 막을 방법은 많아요.\n수입량을 정하거나 검사를 까다롭게 하는 식이에요."}, {"type": "table", "title": "수단별로 초과이윤이 가는 곳", "columns": ["수단", "방식", "가운데 몫"], "rows": [["관세", "가격에 세금", "정부 (관세 수입)"], ["수입할당제", "수입량을 정함", "수입 면허를 받은 수입업자"], ["수출자율규제", "수출국이 스스로 줄임", "수출국 수출업자"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1199,'수입할당제','일정 기간 들여올 수 있는 수입량을 정해 그 이상은 막는 제도','수입할당제(쿼터)는 수입 물량에 상한을 두는 비관세장벽이다. 수입이 줄어 국내 가격이 오르고, 그 차익은 수입 면허를 받은 수입업자에게 돌아간다. 면허를 얻으려는 지대 추구 행위가 생길 수 있다.','','ㅅㅇㅎㄷㅈ',ARRAY['비관세장벽','수출자율규제','할당관세제도','관세']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "올해는 이 상품을 1만 톤까지만 들여올 수 있다고 정하는 거예요.\n수입이 줄어 값이 오르면 면허를 가진 수입업자가 이득을 봐요."}, {"type": "table", "title": "수입할당제 vs 수출자율규제", "columns": ["구분", "누가 줄이나", "초과이윤"], "rows": [["수입할당제", "수입국", "수입업자"], ["수출자율규제", "수출국", "수출국 기업"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1200,'수출자율규제','수입국 요청에 따라 수출국이 스스로 수출량을 줄이는 무역 제한','수출자율규제는 수입국의 압력으로 수출국이 자발적인 형식을 빌려 수출 물량을 제한하는 비관세장벽이다. 효과는 수입할당과 비슷하지만 가격 상승으로 생기는 초과이윤이 수출국 기업에 돌아간다. 신보호무역주의의 대표 수단으로 쓰였다.','','ㅅㅊㅈㅇㄱㅈ',ARRAY['비관세장벽','수입할당제','신보호무역주의']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "수입국이 \"알아서 덜 보내 달라\"고 요구하고 수출국이 따르는 방식이에요.\n물량이 줄어 값이 오르면 그 이득은 수출국 기업이 가져가요."}, {"type": "flow", "title": "수출자율규제 흐름", "steps": ["수입국의 통상 압력", "수출국이 물량 제한", "수입국 내 가격 상승", "초과이윤 → 수출국 기업"]}]'::jsonb,ARRAY['tesat']::text[]),
(1201,'덤핑방지관세','외국 기업이 정상가격보다 싸게 수출해 국내 산업이 피해를 볼 때 매기는 관세','덤핑방지관세는 외국 기업이 자국 판매가나 원가보다 낮은 값으로 수출하는 덤핑에 대응해 차이만큼 부과하는 관세다. 반덤핑관세라고도 한다. 정부 보조금에 대응하는 상계관세와 달리 기업의 가격 행위가 대상이다.','','ㄷㅍㅂㅈㄱㅅ',ARRAY['상계관세','보복관세','긴급수입제한조치','관세']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "외국 회사가 시장을 차지하려고 원가보다 싸게 팔면 국내 회사가 버티기 어려워요.\n그 가격 차이만큼 세금을 매겨 공정하게 맞추는 거예요."}, {"type": "table", "title": "헷갈리는 관세 구분", "columns": ["관세", "언제 매기나"], "rows": [["덤핑방지관세", "외국 기업의 덤핑 수출"], ["상계관세", "수출국 정부 보조금"], ["보복관세", "상대국의 일방적 관세 인상"], ["긴급관세", "수입 급증으로 국내 피해"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1202,'양허관세','국제 협정에서 약속해 그보다 높게 올릴 수 없는 관세율','양허관세는 WTO 협상이나 무역협정에서 각국이 품목별로 상한을 약속한 관세율이다. 실제로 적용하는 실행관세는 이보다 낮을 수 있지만 높게 올리면 협정 위반이 된다. 무역 상대국에 관세 수준을 예측할 수 있게 해 준다.','','ㅇㅎㄱㅅ',ARRAY['세계무역기구(WTO)','관세','자유무역협정(FTA)']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "여기까지만 관세를 매기겠다고 다른 나라에 약속한 한도예요.\n그 밑으로는 자유롭게 정해도 되지만 위로는 못 올려요."}, {"type": "table", "title": "양허관세 vs 실행관세", "columns": ["구분", "뜻"], "rows": [["양허관세", "협정으로 약속한 상한 세율"], ["실행관세", "실제로 적용하는 세율 (상한 이하)"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1203,'자본수지','자본이전과 특허권 같은 비생산·비금융자산 거래를 기록한 국제수지 항목','자본수지는 국제수지표에서 채무 면제나 해외 이주비 같은 자본이전과, 특허권·상표권 자체의 매매를 기록한다. 주식·채권 투자나 해외 공장 설립은 자본수지가 아니라 금융계정에 들어간다. 규모가 작아 경상수지와 금융계정에 비해 비중이 낮다.','','ㅈㅂㅅㅈ',ARRAY['국제수지표','경상수지','금융계정','오차 및 누락']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "대가 없이 넘겨주는 자산이나 특허권 자체를 사고판 기록이에요.\n주식이나 채권 투자는 여기가 아니에요."}, {"type": "table", "title": "국제수지표의 큰 틀", "columns": ["계정", "예"], "rows": [["경상수지", "수출입, 여행, 배당·이자, 송금"], ["자본수지", "채무 면제, 특허권 자체 매매"], ["금융계정", "해외 공장, 주식·채권, 외환보유액"], ["오차 및 누락", "통계 차이"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1204,'금융계정','직접투자, 증권투자, 파생상품, 기타투자, 준비자산 거래를 기록한 국제수지 항목','금융계정은 거주자와 비거주자 사이 금융자산과 부채의 거래를 기록한다. 해외 공장 설립(직접투자), 외국 주식·채권 매매(증권투자), 대출·예금(기타투자), 외환보유액 증감(준비자산)이 여기에 들어간다. 순자산이 늘면 플러스로 기록되며 경상수지 흑자는 대개 금융계정 플러스로 나타난다.','','ㄱㅇㄱㅈ',ARRAY['국제수지표','자본수지','직접투자','외환보유액']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "수출로 번 달러를 해외 주식에 넣거나 은행에 두면 그 기록이 여기 남아요.\n해외 자산이 늘면 플러스예요."}, {"type": "table", "title": "헷갈리는 분류", "columns": ["거래", "들어가는 곳"], "rows": [["해외 주식 매입", "금융계정"], ["해외 주식 배당", "본원소득수지"], ["외환보유액 증가", "금융계정 (준비자산)"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1205,'오차 및 누락','국제수지표의 통계 차이를 맞추기 위해 넣는 조정 항목','오차 및 누락은 거래가 실제로는 한 번 일어나지만 자료 출처와 시점이 달라 기록이 맞지 않는 부분을 메우는 항목이다. 이론상 경상수지 + 자본수지 - 금융계정은 0이어야 하므로 그 차이를 여기에 둔다. 규모가 크면 통계에 잡히지 않는 자금 흐름이 있다는 신호로 보기도 한다.','','ㅇㅊㅁㄴㄹ',ARRAY['국제수지표','복식부기','자본수지','금융계정']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "가계부를 맞춰 보니 몇천 원이 비면 \"기타\"로 적어 두잖아요.\n국제수지표에서 그 칸이 오차 및 누락이에요."}, {"type": "flow", "title": "국제수지 항등식", "steps": ["경상수지", "+ 자본수지", "- 금융계정", "+ 오차 및 누락 = 0"]}]'::jsonb,ARRAY['tesat']::text[]),
(1206,'복식부기','한 거래를 들어온 쪽과 나간 쪽 두 곳에 같은 금액으로 기록하는 방식','복식부기는 모든 거래를 대변과 차변 두 번 기록해 합계가 늘 일치하도록 하는 기록 원칙이다. 국제수지표도 이 원칙을 따르므로 이론상 전체 합이 항상 0이 된다. 예를 들어 상품을 수출하면 경상수지 수출과 금융계정 자산 증가가 함께 기록된다.','','ㅂㅅㅂㄱ',ARRAY['국제수지표','오차 및 누락','경상수지','금융계정']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "자동차를 팔면 차는 나가고 달러가 들어오죠.\n두 사건을 함께 적으니 장부가 늘 맞아떨어져요."}, {"type": "table", "title": "한 거래 = 두 번 기록 (예시)", "columns": ["거래", "경상수지", "금융계정"], "rows": [["자동차 10만 달러 수출", "+10 (상품 수출)", "+10 (받은 달러)"], ["미국 주식 2만 달러 매입", "-", "+2 주식 / -2 달러"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1207,'거주자','국적과 상관없이 한 나라에 주로 머물며 경제활동을 하는 개인과 기업','거주자는 국제수지와 외환 거래에서 국적이 아니라 경제적 이해의 중심지가 어디인지로 정하는 개념이다. 우리나라에 사는 외국인은 거주자이고, 해외에 오래 사는 한국인은 비거주자일 수 있다. 국제수지표는 거주자와 비거주자 사이의 거래를 기록한다.','','ㄱㅈㅈ',ARRAY['국제수지(BOP)','국제수지표','국민총소득(GNI)']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "여권이 아니라 어디서 살고 일하는지가 기준이에요.\n한국에서 일하는 외국인 직원은 우리나라 거주자예요."}, {"type": "table", "title": "거주자일까?", "columns": ["사례", "판단"], "rows": [["우리나라에 사는 외국인", "거주자"], ["해외 지점에서 오래 일하는 한국인", "비거주자일 수 있음"], ["국내에 있는 외국계 기업", "거주자"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1208,'명목환율','은행이나 환전소에서 두 나라 돈을 바꾸는 비율 그대로의 값','명목환율은 1달러 = 몇 원처럼 서로 다른 통화의 교환 비율을 그대로 나타낸 것이다. 두 나라의 물가를 반영해 물건끼리의 교환 비율로 바꾼 것이 실질환율이며, 실질환율 = 명목환율 × 외국 물가 ÷ 국내 물가다. 뉴스에서 말하는 환율은 대부분 명목환율이다.','','ㅁㅁㅎㅇ',ARRAY['환율','실질실효환율','구매력평가 환율','기준환율']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "환전소 전광판에 뜨는 1달러 = 1,300원 같은 숫자가 명목환율이에요.\n물가까지 따지면 실질환율이 돼요."}, {"type": "table", "title": "명목환율 vs 실질환율", "columns": ["구분", "뜻"], "rows": [["명목환율", "돈과 돈의 교환 비율"], ["실질환율", "두 나라 물가를 반영한 물건끼리의 교환 비율"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1209,'관리변동환율제','시장에서 환율이 정해지되 급변할 때만 당국이 개입하는 제도','관리변동환율제는 외환 수요와 공급으로 환율이 결정되도록 두면서, 지나치게 쏠리거나 급변하면 정부와 중앙은행이 외환을 사고팔아 속도를 조절하는 제도다. 고정환율제의 안정성과 변동환율제의 유연성을 절충한 방식이다. 개입 시점과 규모를 판단하기 어렵다는 한계가 있다.','','ㄱㄹㅂㄷㅎㅇㅈ',ARRAY['자유변동환율제도','고정환율제도','시장평균환율제도','외환보유액']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "평소엔 시장에 맡기다가 환율이 너무 빨리 움직이면 당국이 브레이크를 밟아요."}, {"type": "table", "title": "환율 제도 비교", "columns": ["제도", "결정 방식", "단점"], "rows": [["고정환율제", "정부가 고정", "외환보유액 부담"], ["변동환율제", "외환 수요·공급", "환위험, 환투기"], ["관리변동환율제", "시장 + 급변 시 개입", "개입 시점 판단이 어려움"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1210,'원화 강세','외국 돈에 비해 원화 가치가 올라 환율이 내려가는 현상','원화 강세는 외환시장의 수요와 공급에 따라 원화 가치가 오르는 것으로, 원/달러 환율이 하락하는 것과 같은 뜻이다. 수입품과 해외여행 비용이 싸지고 외화 부채 부담이 줄지만 수출 기업의 가격 경쟁력은 떨어진다. 수출 증가로 달러가 들어오거나 외국인 투자가 유입될 때 나타나기 쉽다.','','ㅇㅎㄱㅅ',ARRAY['원화 약세','환율','평가절상','환차손']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "1달러에 1,300원이던 게 1,100원이 되면 원화 값이 오른 거예요.\n같은 원화로 달러를 더 많이 살 수 있어요."}, {"type": "table", "title": "원화 강세 vs 원화 약세", "columns": ["구분", "원화 강세 (환율↓)", "원화 약세 (환율↑)"], "rows": [["수출 기업", "불리", "유리"], ["수입 기업", "유리", "불리"], ["수입 물가", "내려가요", "올라가요"], ["외화 부채 부담", "줄어요", "늘어요"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1211,'원화 약세','외국 돈에 비해 원화 가치가 떨어져 환율이 올라가는 현상','원화 약세는 원화 가치가 내려가는 것으로, 원/달러 환율이 상승하는 것과 같은 뜻이다. 수출 기업의 가격 경쟁력은 좋아지지만 수입 물가가 올라 물가 부담이 커지고 외화 부채 상환 부담도 늘어난다. 수입 증가로 달러가 빠져나가거나 외국인 투자가 회수될 때 나타나기 쉽다.','','ㅇㅎㅇㅅ',ARRAY['원화 강세','환율','평가절하','수출입물가지수']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "1달러에 1,100원이던 게 1,300원이 되면 원화 값이 떨어진 거예요.\n환율 숫자는 오르는데 원화 가치는 내려가요."}, {"type": "flow", "title": "원화 약세가 물가로 번지는 길", "steps": ["환율 상승", "수입품 원화 가격↑", "원자재·생산비↑", "소비자물가 상승 압력"]}]'::jsonb,ARRAY['tesat']::text[]),
(1212,'평가절상','고정환율제에서 정부가 자국 통화의 공식 가치를 인위적으로 높이는 조치','평가절상은 정부나 중앙은행이 고정된 환율 수준을 바꿔 자국 통화 가치를 올리는 것이다. 시장에서 저절로 통화 가치가 오르는 원화 강세와 달리 정책 결정으로 이루어진다. 수입품이 싸지는 대신 수출 경쟁력은 약해진다.','','ㅍㄱㅈㅅ',ARRAY['평가절하','고정환율제도','원화 강세']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "정부가 \"오늘부터 우리 돈 1단위는 달러를 더 많이 쳐 준다\"고 발표하는 거예요.\n시장이 아니라 정부가 바꾼다는 점이 핵심이에요."}, {"type": "table", "title": "평가절상·절하 vs 강세·약세", "columns": ["구분", "누가", "제도"], "rows": [["평가절상·평가절하", "정부·중앙은행이 인위적으로", "고정환율제"], ["원화 강세·약세", "시장의 수요·공급으로", "변동환율제"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1213,'평가절하','고정환율제에서 정부가 자국 통화의 공식 가치를 인위적으로 낮추는 조치','평가절하는 정부나 중앙은행이 고정된 환율 수준을 바꿔 자국 통화 가치를 내리는 것이다. 수출 경쟁력을 높이거나 외환보유액 고갈을 막으려고 쓰인다. 수입 물가가 올라 인플레이션을 부를 수 있고, 다른 나라의 맞대응을 부르기도 한다.','','ㅍㄱㅈㅎ',ARRAY['평가절상','고정환율제도','원화 약세','근린궁핍화정책']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "정부가 자기 나라 돈 가치를 일부러 낮추면 수출품이 해외에서 싸져요.\n대신 수입품은 비싸져요."}, {"type": "flow", "title": "평가절하의 효과", "steps": ["통화 가치 인하 발표", "수출품 외화 가격↓", "수출 증가 기대", "수입 물가↑"]}]'::jsonb,ARRAY['tesat']::text[])
